parameters.jsCode:
const data = $json;


// =========================================
// ERROR TRIGGER SECTIONS
// =========================================

const execution =
  data.execution &&
  typeof data.execution === 'object'
    ? data.execution
    : {};

const workflow =
  data.workflow &&
  typeof data.workflow === 'object'
    ? data.workflow
    : {};

const error =
  execution.error &&
  typeof execution.error === 'object'
    ? execution.error
    : (
        data.error &&
        typeof data.error === 'object'
          ? data.error
          : {}
      );


// =========================================
// WORKFLOW DETAILS
// =========================================

const workflowId =
  String(
    workflow.id ||
    data.workflowId ||
    ''
  ).trim();

const workflowName =
  String(
    workflow.name ||
    data.workflowName ||
    'Unknown Workflow'
  ).trim();


// =========================================
// EXECUTION DETAILS
// =========================================

const executionId =
  String(
    execution.id ||
    data.executionId ||
    ''
  ).trim();

const executionUrl =
  String(
    execution.url ||
    data.executionUrl ||
    ''
  ).trim();

const executionMode =
  String(
    execution.mode ||
    data.mode ||
    'unknown'
  ).trim();

const lastNodeExecuted =
  String(
    execution.lastNodeExecuted ||
    data.lastNodeExecuted ||
    'Unknown Node'
  ).trim();


// =========================================
// ERROR DETAILS
// =========================================

const errorMessage =
  String(
    error.message ||
    data.errorMessage ||
    data.message ||
    'Unknown workflow error'
  ).trim();

const errorName =
  String(
    error.name ||
    data.errorName ||
    'WorkflowError'
  ).trim();

const errorStack =
  String(
    error.stack ||
    data.stack ||
    ''
  ).trim();


// =========================================
// RETRY DETAILS
// =========================================

const retryOf =
  execution.retryOf !== undefined &&
  execution.retryOf !== null
    ? String(execution.retryOf)
    : null;


// =========================================
// OUTPUT
// =========================================

return {
  json: {
    event_type:
      'WORKFLOW_ERROR',

    workflow_id:
      workflowId || null,

    workflow_name:
      workflowName,

    execution_id:
      executionId || null,

    execution_url:
      executionUrl || null,

    execution_mode:
      executionMode,

    last_node_executed:
      lastNodeExecuted,

    error_name:
      errorName,

    error_message:
      errorMessage,

    error_stack:
      errorStack || null,

    retry_of:
      retryOf,

    occurred_at:
      $now.toISO()
  }
};

